 overview TEXT NOT NULL DEFAULT '',
 original_title TEXT NOT NULL DEFAULT '',
 tagline TEXT NOT NULL DEFAULT '',
 show_ranges TEXT NOT NULL DEFAULT '',
 show_settings_present INTEGER NOT NULL DEFAULT 0 CHECK(typeof(show_settings_present)='integer' AND show_settings_present IN(0,1) AND (show_settings_present=0 OR kind=2)) CHECK(show_settings_present=1 OR (hide_seasons=0 AND absolute_numbering=0 AND newest_first=0 AND show_ranges='')),
 CHECK((playback_origin_incarnation IS NULL)=(playback_origin_revision IS NULL)),
 FOREIGN KEY(library_id,parent_id) REFERENCES catalog_entities(library_id,id),
