 FOREIGN KEY(active_generation_ref,id) REFERENCES lc_generations(id,channel_id)
) STRICT;

CREATE TABLE lc_entries(
 generation_id TEXT NOT NULL REFERENCES lc_generations(id),
 occurrence_id TEXT NOT NULL,
