 start_ms INTEGER NOT NULL,
 end_ms INTEGER NOT NULL CHECK(end_ms>start_ms),
 item_id INTEGER NOT NULL,
 asset_id TEXT NOT NULL,
 library_id TEXT NOT NULL,
 source_fence TEXT NOT NULL,
 title TEXT NOT NULL,
 rule_id TEXT NOT NULL,
 block_id TEXT NOT NULL,
 source_offset_ms INTEGER NOT NULL,
 slate_reason TEXT NOT NULL,
 PRIMARY KEY(generation_id,occurrence_id),
 UNIQUE(generation_id,start_ms),
 CHECK(typeof("generation_id")IN('null','text')),
 CHECK(typeof("occurrence_id")IN('null','text')),
 CHECK(typeof("channel_id")IN('null','text')),
 CHECK(typeof("start_ms")IN('null','integer')),
 CHECK(typeof("end_ms")IN('null','integer')),
 CHECK(typeof("item_id")IN('null','integer')),
 CHECK(typeof("asset_id")IN('null','text')),
 CHECK(typeof("library_id")IN('null','text')),
 CHECK(typeof("source_fence")IN('null','text')),
 CHECK(typeof("title")IN('null','text')),
 CHECK(typeof("rule_id")IN('null','text')),
 CHECK(typeof("block_id")IN('null','text')),
 CHECK(typeof("source_offset_ms")IN('null','integer')),
 CHECK(typeof("slate_reason")IN('null','text'))
);

CREATE TABLE lc_generations(
 id TEXT PRIMARY KEY,
 channel_id TEXT NOT NULL REFERENCES lc_channels(id),
 config_revision INTEGER NOT NULL,
 config_json TEXT NOT NULL,
 catalog_fence TEXT NOT NULL,
 seed TEXT NOT NULL,
 status TEXT NOT NULL,
 phase TEXT NOT NULL,
 base_generation TEXT NOT NULL,
 start_ms INTEGER NOT NULL,
 end_ms INTEGER NOT NULL,
 boundary_ms INTEGER NOT NULL,
 copy_after_ms INTEGER NOT NULL DEFAULT -1,
 scan_rule INTEGER NOT NULL DEFAULT 0,
 scan_after TEXT NOT NULL DEFAULT '',
 cursor_ms INTEGER NOT NULL,
 candidate_count INTEGER NOT NULL DEFAULT 0,
 unresolved_count INTEGER NOT NULL DEFAULT 0,
 lease_token TEXT NOT NULL DEFAULT '',
 lease_until_ms INTEGER NOT NULL DEFAULT 0,
 created_ms INTEGER NOT NULL,
 published_ms INTEGER NOT NULL DEFAULT 0,
 error_code TEXT NOT NULL DEFAULT '',
 play_history_fence INTEGER NOT NULL DEFAULT 0 CHECK(play_history_fence>=0),
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 create_operation_id BLOB NOT NULL CHECK(length(create_operation_id)=16),
 birth_request_digest BLOB NOT NULL CHECK(length(birth_request_digest)=32),
 last_command_sequence INTEGER NOT NULL DEFAULT 1 CHECK(last_command_sequence>=1),
 acknowledged_command_sequence INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged_command_sequence>=0 AND acknowledged_command_sequence<=last_command_sequence),
 stage_revision INTEGER NOT NULL DEFAULT 1 CHECK(stage_revision>0),
 staged_bytes INTEGER NOT NULL DEFAULT 0 CHECK(staged_bytes>=0),
 entry_count INTEGER NOT NULL DEFAULT 0 CHECK(entry_count>=0),
 entry_digest BLOB NOT NULL CHECK(length(entry_digest)=32),
 verified_entry_count INTEGER NOT NULL DEFAULT 0 CHECK(verified_entry_count>=0 AND verified_entry_count<=entry_count),
 verify_after_ms INTEGER NOT NULL DEFAULT -1 CHECK(verify_after_ms>=-1),
 verify_end_ms INTEGER NOT NULL CHECK(verify_end_ms>=start_ms),
 verified_entry_digest BLOB NOT NULL CHECK(length(verified_entry_digest)=32),
 schedule_sealed INTEGER NOT NULL DEFAULT 0 CHECK(schedule_sealed IN(0,1)),
 reclaim_family TEXT NOT NULL DEFAULT 'none' CHECK(reclaim_family IN('none','entries','candidates','rule_state','used','generation','complete')),
 reclaim_key TEXT NOT NULL DEFAULT '',
 reclaim_subkey INTEGER NOT NULL DEFAULT 0 CHECK(reclaim_subkey>=0),
 pending_base_generation TEXT GENERATED ALWAYS AS (CASE WHEN status='pending' THEN NULLIF(base_generation,'') ELSE NULL END) STORED,
 receipt_rows INTEGER NOT NULL DEFAULT 0 CHECK(receipt_rows>=0),
 receipt_variable_bytes INTEGER NOT NULL DEFAULT 0 CHECK(receipt_variable_bytes>=0),
 receipt_reclaim_after_sequence INTEGER NOT NULL DEFAULT 0 CHECK(receipt_reclaim_after_sequence>=0),
 receipt_reclaim_due_ms INTEGER CHECK(receipt_reclaim_due_ms IS NULL OR receipt_reclaim_due_ms>=0),
 reclaim_command_sequence INTEGER,
 reclaim_operation_id BLOB CHECK(reclaim_operation_id IS NULL OR length(reclaim_operation_id)=16),
 reclaim_request_digest BLOB CHECK(reclaim_request_digest IS NULL OR length(reclaim_request_digest)=32),
 reclaim_command_kind TEXT,
 reclaim_result_version INTEGER,
 reclaim_captured_acknowledged_sequence INTEGER,
 reclaim_old_after_sequence INTEGER,
 reclaim_removed_sequence INTEGER,
 reclaim_removed_count INTEGER,
 reclaim_removed_variable_bytes INTEGER,
 reclaim_result_after_sequence INTEGER,
 reclaim_result_no_next INTEGER,
 reclaim_applied_ms INTEGER,
 reclaim_result_count INTEGER,
 reclaim_result_digest BLOB CHECK(reclaim_result_digest IS NULL OR length(reclaim_result_digest)=32),
 control_variable_bytes INTEGER GENERATED ALWAYS AS (coalesce(length(CAST(id AS BLOB)),0)+coalesce(length(CAST(channel_id AS BLOB)),0)+coalesce(length(CAST(config_json AS BLOB)),0)+coalesce(length(CAST(catalog_fence AS BLOB)),0)+coalesce(length(CAST(seed AS BLOB)),0)+coalesce(length(CAST(status AS BLOB)),0)+coalesce(length(CAST(phase AS BLOB)),0)+coalesce(length(CAST(base_generation AS BLOB)),0)+coalesce(length(CAST(scan_after AS BLOB)),0)+coalesce(length(CAST(lease_token AS BLOB)),0)+coalesce(length(CAST(error_code AS BLOB)),0)+coalesce(length(command_incarnation),0)+coalesce(length(create_operation_id),0)+coalesce(length(birth_request_digest),0)+coalesce(length(entry_digest),0)+coalesce(length(verified_entry_digest),0)+coalesce(length(CAST(reclaim_family AS BLOB)),0)+coalesce(length(CAST(reclaim_key AS BLOB)),0)+coalesce(length(CAST(pending_base_generation AS BLOB)),0)+coalesce(length(reclaim_operation_id),0)+coalesce(length(reclaim_request_digest),0)+coalesce(length(CAST(reclaim_command_kind AS BLOB)),0)+coalesce(length(reclaim_result_digest),0)) VIRTUAL,
 FOREIGN KEY(pending_base_generation,channel_id) REFERENCES lc_generations(id,channel_id),
 CONSTRAINT lc_schedule_seal CHECK(schedule_sealed=0 OR (entry_count>0 AND verified_entry_count=entry_count AND verify_end_ms=cursor_ms AND cursor_ms>=end_ms AND verified_entry_digest=entry_digest)),
 CHECK(last_command_sequence-acknowledged_command_sequence<=1),
 CHECK(receipt_reclaim_after_sequence<=acknowledged_command_sequence),
 CHECK((receipt_rows=0)=(receipt_variable_bytes=0)),
 CONSTRAINT lc_generations_receipt_slot CHECK((reclaim_command_sequence IS NULL AND reclaim_operation_id IS NULL AND reclaim_request_digest IS NULL AND reclaim_command_kind IS NULL AND reclaim_result_version IS NULL AND reclaim_captured_acknowledged_sequence IS NULL AND reclaim_old_after_sequence IS NULL AND reclaim_removed_sequence IS NULL AND reclaim_removed_count IS NULL AND reclaim_removed_variable_bytes IS NULL AND reclaim_result_after_sequence IS NULL AND reclaim_result_no_next IS NULL AND reclaim_applied_ms IS NULL AND reclaim_result_count IS NULL AND reclaim_result_digest IS NULL) OR (reclaim_command_sequence IS NOT NULL AND reclaim_operation_id IS NOT NULL AND reclaim_request_digest IS NOT NULL AND reclaim_command_kind IS NOT NULL AND reclaim_result_version IS NOT NULL AND reclaim_captured_acknowledged_sequence IS NOT NULL AND reclaim_old_after_sequence IS NOT NULL AND reclaim_removed_count IS NOT NULL AND reclaim_removed_variable_bytes IS NOT NULL AND reclaim_result_after_sequence IS NOT NULL AND reclaim_result_no_next IS NOT NULL AND reclaim_applied_ms IS NOT NULL AND reclaim_result_count IS NOT NULL AND reclaim_result_digest IS NOT NULL AND reclaim_command_sequence>0 AND reclaim_command_sequence<=last_command_sequence AND reclaim_command_kind='lc_receipt_reclaim' AND reclaim_result_version=1 AND reclaim_result_count=1 AND reclaim_captured_acknowledged_sequence>=0 AND reclaim_captured_acknowledged_sequence<reclaim_command_sequence AND reclaim_old_after_sequence>=0 AND reclaim_old_after_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_captured_acknowledged_sequence<=acknowledged_command_sequence AND reclaim_result_after_sequence=receipt_reclaim_after_sequence AND reclaim_result_no_next IN(0,1) AND reclaim_applied_ms>=0 AND ((reclaim_removed_count=0 AND reclaim_removed_sequence IS NULL AND reclaim_removed_variable_bytes=0 AND reclaim_result_after_sequence=reclaim_old_after_sequence AND reclaim_result_no_next=1) OR (reclaim_removed_count=1 AND reclaim_removed_sequence IS NOT NULL AND reclaim_removed_sequence>reclaim_old_after_sequence AND reclaim_removed_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_removed_variable_bytes>0 AND reclaim_result_after_sequence=reclaim_removed_sequence)))),
 CHECK(typeof(control_variable_bytes)='integer' AND control_variable_bytes>=0)
) STRICT;

CREATE TABLE lc_maintenance_cursor(
