 attribute_country TEXT,
 attribute_catchup TEXT,
 attribute_catchup_source TEXT,
 attribute_catchup_days TEXT,
 has_live_channel_logos INTEGER NOT NULL DEFAULT 0 CHECK(has_live_channel_logos IN(0,1)),
 logo_url TEXT,
