) WITHOUT ROWID, STRICT;

CREATE TABLE live_logo_jobs(
 source_id TEXT PRIMARY KEY REFERENCES live_source_identities(id),
 generation_id TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','complete','failed')),
 imported INTEGER NOT NULL DEFAULT 0,
 skipped INTEGER NOT NULL DEFAULT 0,
 last_channel TEXT NOT NULL DEFAULT '',
 job_lease_owner INTEGER NOT NULL DEFAULT 0 CHECK(job_lease_owner>=0),
 job_lease_generation INTEGER NOT NULL DEFAULT 0 CHECK(job_lease_generation>=0),
 job_lease_expires_ms INTEGER NOT NULL DEFAULT 0 CHECK(job_lease_expires_ms>=0),
 job_attempts INTEGER NOT NULL DEFAULT 0 CHECK(job_attempts BETWEEN 0 AND 4294967295),
 job_next_attempt_ms INTEGER CHECK(job_next_attempt_ms IS NULL OR job_next_attempt_ms>=0),
 job_due_ms INTEGER GENERATED ALWAYS AS (CASE WHEN job_next_attempt_ms IS NULL THEN NULL ELSE max(job_next_attempt_ms,job_lease_expires_ms) END) STORED,
 job_revision INTEGER NOT NULL DEFAULT 1 CHECK(job_revision>0)
) WITHOUT ROWID, STRICT;

CREATE TABLE live_operations(
 request_id TEXT PRIMARY KEY,
 input_hash TEXT NOT NULL,
 source_id TEXT NOT NULL REFERENCES live_source_identities(id),
 generation_id TEXT NOT NULL,
 expected_revision INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('staging','published','superseded')),
 result_revision INTEGER NOT NULL DEFAULT 0,
 result_state TEXT NOT NULL DEFAULT '',
 published_at TEXT NOT NULL DEFAULT '',
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 create_operation_id BLOB NOT NULL CHECK(length(create_operation_id)=16),
 birth_request_digest BLOB NOT NULL CHECK(length(birth_request_digest)=32),
 last_command_sequence INTEGER NOT NULL DEFAULT 1 CHECK(last_command_sequence>=1),
 acknowledged_command_sequence INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged_command_sequence>=0 AND acknowledged_command_sequence<=last_command_sequence),
 expected_generation TEXT NOT NULL DEFAULT '',
 expected_choice_count INTEGER NOT NULL CHECK(expected_choice_count>=0),
 stage_revision INTEGER NOT NULL DEFAULT 1 CHECK(stage_revision>0),
 staged_channel_count INTEGER NOT NULL DEFAULT 0 CHECK(staged_channel_count>=0),
 staged_programme_count INTEGER NOT NULL DEFAULT 0 CHECK(staged_programme_count>=0),
 staged_choice_count INTEGER NOT NULL DEFAULT 0 CHECK(staged_choice_count>=0 AND staged_choice_count<=expected_choice_count),
 staged_bytes INTEGER NOT NULL DEFAULT 0 CHECK(staged_bytes>=0),
 manifest_digest BLOB NOT NULL CHECK(length(manifest_digest)=32),
 stage_digest BLOB NOT NULL CHECK(length(stage_digest)=32),
 sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1)),
 reclaim_family TEXT NOT NULL DEFAULT 'none' CHECK(reclaim_family IN('none','programmes','channels','choices','generation','complete')),
 reclaim_cursor TEXT NOT NULL DEFAULT '',
 receipt_rows INTEGER NOT NULL DEFAULT 0 CHECK(receipt_rows>=0),
 receipt_variable_bytes INTEGER NOT NULL DEFAULT 0 CHECK(receipt_variable_bytes>=0),
 receipt_reclaim_after_sequence INTEGER NOT NULL DEFAULT 0 CHECK(receipt_reclaim_after_sequence>=0),
 receipt_reclaim_due_ms INTEGER CHECK(receipt_reclaim_due_ms IS NULL OR receipt_reclaim_due_ms>=0),
 reclaim_command_sequence INTEGER,
 reclaim_operation_id BLOB CHECK(reclaim_operation_id IS NULL OR length(reclaim_operation_id)=16),
 reclaim_request_digest BLOB CHECK(reclaim_request_digest IS NULL OR length(reclaim_request_digest)=32),
 reclaim_command_kind TEXT,
 reclaim_result_version INTEGER,
 reclaim_captured_acknowledged_sequence INTEGER,
 reclaim_old_after_sequence INTEGER,
 reclaim_removed_sequence INTEGER,
 reclaim_removed_count INTEGER,
 reclaim_removed_variable_bytes INTEGER,
 reclaim_result_after_sequence INTEGER,
 reclaim_result_no_next INTEGER,
 reclaim_applied_ms INTEGER,
 reclaim_result_count INTEGER,
 reclaim_result_digest BLOB CHECK(reclaim_result_digest IS NULL OR length(reclaim_result_digest)=32),
 control_variable_bytes INTEGER GENERATED ALWAYS AS (coalesce(length(CAST(request_id AS BLOB)),0)+coalesce(length(CAST(input_hash AS BLOB)),0)+coalesce(length(CAST(source_id AS BLOB)),0)+coalesce(length(CAST(generation_id AS BLOB)),0)+coalesce(length(CAST(status AS BLOB)),0)+coalesce(length(CAST(result_state AS BLOB)),0)+coalesce(length(CAST(published_at AS BLOB)),0)+coalesce(length(command_incarnation),0)+coalesce(length(create_operation_id),0)+coalesce(length(birth_request_digest),0)+coalesce(length(CAST(expected_generation AS BLOB)),0)+coalesce(length(manifest_digest),0)+coalesce(length(stage_digest),0)+coalesce(length(CAST(reclaim_family AS BLOB)),0)+coalesce(length(CAST(reclaim_cursor AS BLOB)),0)+coalesce(length(reclaim_operation_id),0)+coalesce(length(reclaim_request_digest),0)+coalesce(length(CAST(reclaim_command_kind AS BLOB)),0)+coalesce(length(reclaim_result_digest),0)) VIRTUAL,
 FOREIGN KEY(generation_id,source_id) REFERENCES live_generations(id,source_id),
 CHECK((expected_revision=0)=(expected_generation='')),
 CONSTRAINT live_operation_seal CHECK(sealed=0 OR (staged_channel_count>0 AND staged_choice_count=expected_choice_count AND stage_digest=manifest_digest)),
 CHECK(last_command_sequence-acknowledged_command_sequence<=1),
 CHECK(receipt_reclaim_after_sequence<=acknowledged_command_sequence),
 CHECK((receipt_rows=0)=(receipt_variable_bytes=0)),
 CONSTRAINT live_operations_receipt_slot CHECK((reclaim_command_sequence IS NULL AND reclaim_operation_id IS NULL AND reclaim_request_digest IS NULL AND reclaim_command_kind IS NULL AND reclaim_result_version IS NULL AND reclaim_captured_acknowledged_sequence IS NULL AND reclaim_old_after_sequence IS NULL AND reclaim_removed_sequence IS NULL AND reclaim_removed_count IS NULL AND reclaim_removed_variable_bytes IS NULL AND reclaim_result_after_sequence IS NULL AND reclaim_result_no_next IS NULL AND reclaim_applied_ms IS NULL AND reclaim_result_count IS NULL AND reclaim_result_digest IS NULL) OR (reclaim_command_sequence IS NOT NULL AND reclaim_operation_id IS NOT NULL AND reclaim_request_digest IS NOT NULL AND reclaim_command_kind IS NOT NULL AND reclaim_result_version IS NOT NULL AND reclaim_captured_acknowledged_sequence IS NOT NULL AND reclaim_old_after_sequence IS NOT NULL AND reclaim_removed_count IS NOT NULL AND reclaim_removed_variable_bytes IS NOT NULL AND reclaim_result_after_sequence IS NOT NULL AND reclaim_result_no_next IS NOT NULL AND reclaim_applied_ms IS NOT NULL AND reclaim_result_count IS NOT NULL AND reclaim_result_digest IS NOT NULL AND reclaim_command_sequence>0 AND reclaim_command_sequence<=last_command_sequence AND reclaim_command_kind='guide_receipt_reclaim' AND reclaim_result_version=1 AND reclaim_result_count=1 AND reclaim_captured_acknowledged_sequence>=0 AND reclaim_captured_acknowledged_sequence<reclaim_command_sequence AND reclaim_old_after_sequence>=0 AND reclaim_old_after_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_captured_acknowledged_sequence<=acknowledged_command_sequence AND reclaim_result_after_sequence=receipt_reclaim_after_sequence AND reclaim_result_no_next IN(0,1) AND reclaim_applied_ms>=0 AND ((reclaim_removed_count=0 AND reclaim_removed_sequence IS NULL AND reclaim_removed_variable_bytes=0 AND reclaim_result_after_sequence=reclaim_old_after_sequence AND reclaim_result_no_next=1) OR (reclaim_removed_count=1 AND reclaim_removed_sequence IS NOT NULL AND reclaim_removed_sequence>reclaim_old_after_sequence AND reclaim_removed_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_removed_variable_bytes>0 AND reclaim_result_after_sequence=reclaim_removed_sequence)))),
 CHECK(typeof(control_variable_bytes)='integer' AND control_variable_bytes>=0)
) STRICT;

