 mp_reclaim_request_digest BLOB CHECK(mp_reclaim_request_digest IS NULL OR length(mp_reclaim_request_digest)=32) CHECK(mp_reclaim_request_digest IS NULL OR typeof(mp_reclaim_request_digest) IN('blob')),
