 ip_receipt_variable_bytes INTEGER NOT NULL DEFAULT 0 CHECK(typeof(ip_receipt_variable_bytes)='integer' AND ip_receipt_variable_bytes>=0),
 ip_receipt_reclaim_after_sequence INTEGER NOT NULL DEFAULT 0 CHECK(typeof(ip_receipt_reclaim_after_sequence)='integer' AND ip_receipt_reclaim_after_sequence>=0 AND ip_receipt_reclaim_after_sequence<=acknowledged_command_sequence),
 ip_receipt_reclaim_due_ms INTEGER CHECK(typeof(ip_receipt_reclaim_due_ms) IN('null','integer') AND (ip_receipt_reclaim_due_ms IS NULL OR ip_receipt_reclaim_due_ms>=0)),
 ip_reclaim_command_sequence INTEGER CHECK(typeof(ip_reclaim_command_sequence) IN('null','integer') AND (ip_reclaim_command_sequence IS NULL OR ip_reclaim_command_sequence>0)),
 ip_reclaim_operation_id BLOB CHECK(typeof(ip_reclaim_operation_id) IN('null','blob') AND (ip_reclaim_operation_id IS NULL OR length(ip_reclaim_operation_id)=16)),
 ip_reclaim_request_digest BLOB CHECK(typeof(ip_reclaim_request_digest) IN('null','blob') AND (ip_reclaim_request_digest IS NULL OR length(ip_reclaim_request_digest)=32)),
 ip_reclaim_applied_ms INTEGER CHECK(typeof(ip_reclaim_applied_ms) IN('null','integer') AND (ip_reclaim_applied_ms IS NULL OR ip_reclaim_applied_ms>=0)),
 ip_reclaim_result_digest BLOB CHECK(typeof(ip_reclaim_result_digest) IN('null','blob') AND (ip_reclaim_result_digest IS NULL OR length(ip_reclaim_result_digest)=32)),
 ip_reclaim_captured_ack INTEGER CHECK(typeof(ip_reclaim_captured_ack) IN('null','integer') AND (ip_reclaim_captured_ack IS NULL OR ip_reclaim_captured_ack>=0)),
 ip_reclaim_old_cursor INTEGER CHECK(typeof(ip_reclaim_old_cursor) IN('null','integer') AND (ip_reclaim_old_cursor IS NULL OR ip_reclaim_old_cursor>=0)),
