 ip_reclaim_removed_bytes INTEGER CHECK(typeof(ip_reclaim_removed_bytes) IN('null','integer') AND (ip_reclaim_removed_bytes IS NULL OR ip_reclaim_removed_bytes>=0)),
 ip_reclaim_result_cursor INTEGER CHECK(typeof(ip_reclaim_result_cursor) IN('null','integer') AND (ip_reclaim_result_cursor IS NULL OR ip_reclaim_result_cursor>=0)),
 ip_reclaim_no_next INTEGER CHECK(typeof(ip_reclaim_no_next) IN('null','integer') AND (ip_reclaim_no_next IS NULL OR ip_reclaim_no_next IN(0,1))) CHECK((ip_receipt_rows=0)=(ip_receipt_variable_bytes=0)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_operation_id IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_request_digest IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_applied_ms IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_result_digest IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_captured_ack IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_old_cursor IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_removed_count IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_removed_bytes IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_result_cursor IS NULL)) CHECK((ip_reclaim_command_sequence IS NULL)=(ip_reclaim_no_next IS NULL)) CHECK(ip_reclaim_command_sequence IS NULL OR (ip_reclaim_command_sequence<=last_command_sequence AND ip_reclaim_command_sequence-ip_reclaim_captured_ack=1 AND ip_reclaim_captured_ack<=acknowledged_command_sequence AND ip_reclaim_old_cursor<=ip_reclaim_result_cursor AND ip_reclaim_result_cursor<=ip_reclaim_captured_ack AND ip_receipt_reclaim_after_sequence=ip_reclaim_result_cursor AND (ip_reclaim_no_next=0 OR ip_reclaim_result_cursor=ip_reclaim_captured_ack) AND (ip_reclaim_removed_count<>0 OR ip_reclaim_removed_bytes=0))),
 ip_control_variable_bytes INTEGER GENERATED ALWAYS AS(coalesce(length(ip_reclaim_operation_id),0)+coalesce(length(ip_reclaim_request_digest),0)+coalesce(length(ip_reclaim_result_digest),0)) VIRTUAL CHECK(typeof(ip_control_variable_bytes)='integer' AND ip_control_variable_bytes>=0),
 UNIQUE(provider,id),
 FOREIGN KEY(entity_id,provider,set_subject_kind,set_provider_id,set_id) REFERENCES metadata_publication_sets(entity_id,provider,subject_kind,provider_id,id),
