 CONSTRAINT dvr_capture_retirements_receipt_slot CHECK((reclaim_command_sequence IS NULL AND reclaim_operation_id IS NULL AND reclaim_request_digest IS NULL AND reclaim_command_kind IS NULL AND reclaim_result_version IS NULL AND reclaim_captured_acknowledged_sequence IS NULL AND reclaim_old_after_sequence IS NULL AND reclaim_removed_sequence IS NULL AND reclaim_removed_count IS NULL AND reclaim_removed_variable_bytes IS NULL AND reclaim_result_after_sequence IS NULL AND reclaim_result_no_next IS NULL AND reclaim_applied_ms IS NULL AND reclaim_result_count IS NULL AND reclaim_result_digest IS NULL) OR (reclaim_command_sequence IS NOT NULL AND reclaim_operation_id IS NOT NULL AND reclaim_request_digest IS NOT NULL AND reclaim_command_kind IS NOT NULL AND reclaim_result_version IS NOT NULL AND reclaim_captured_acknowledged_sequence IS NOT NULL AND reclaim_old_after_sequence IS NOT NULL AND reclaim_removed_count IS NOT NULL AND reclaim_removed_variable_bytes IS NOT NULL AND reclaim_result_after_sequence IS NOT NULL AND reclaim_result_no_next IS NOT NULL AND reclaim_applied_ms IS NOT NULL AND reclaim_result_count IS NOT NULL AND reclaim_result_digest IS NOT NULL AND reclaim_command_sequence>0 AND reclaim_command_sequence<=last_command_sequence AND reclaim_command_kind='dvr_capture_receipt_reclaim' AND reclaim_result_version=1 AND reclaim_result_count=1 AND reclaim_captured_acknowledged_sequence>=0 AND reclaim_captured_acknowledged_sequence<reclaim_command_sequence AND reclaim_old_after_sequence>=0 AND reclaim_old_after_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_captured_acknowledged_sequence<=acknowledged_command_sequence AND reclaim_result_after_sequence=receipt_reclaim_after_sequence AND reclaim_result_no_next IN(0,1) AND reclaim_applied_ms>=0 AND ((reclaim_removed_count=0 AND reclaim_removed_sequence IS NULL AND reclaim_removed_variable_bytes=0 AND reclaim_result_after_sequence=reclaim_old_after_sequence AND reclaim_result_no_next=1) OR (reclaim_removed_count=1 AND reclaim_removed_sequence IS NOT NULL AND reclaim_removed_sequence>reclaim_old_after_sequence AND reclaim_removed_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_removed_variable_bytes>0 AND reclaim_result_after_sequence=reclaim_removed_sequence)))),
 CHECK(typeof("last_command_sequence") IN('null','integer')),
 CHECK(typeof("acknowledged_command_sequence") IN('null','integer')),
 CHECK(typeof("receipt_rows") IN('null','integer')),
 CHECK(typeof("receipt_variable_bytes") IN('null','integer')),
 CHECK(typeof("receipt_reclaim_after_sequence") IN('null','integer')),
 CHECK(typeof("receipt_reclaim_due_ms") IN('null','integer')),
 CHECK(typeof("reclaim_command_sequence") IN('null','integer')),
 CHECK(typeof("reclaim_operation_id") IN('null','blob')),
 CHECK(typeof("reclaim_request_digest") IN('null','blob')),
 CHECK(typeof("reclaim_command_kind") IN('null','text')),
 CHECK(typeof("reclaim_result_version") IN('null','integer')),
 CHECK(typeof("reclaim_captured_acknowledged_sequence") IN('null','integer')),
 CHECK(typeof("reclaim_old_after_sequence") IN('null','integer')),
 CHECK(typeof("reclaim_removed_sequence") IN('null','integer')),
 CHECK(typeof("reclaim_removed_count") IN('null','integer')),
 CHECK(typeof("reclaim_removed_variable_bytes") IN('null','integer')),
 CHECK(typeof("reclaim_result_after_sequence") IN('null','integer')),
 CHECK(typeof("reclaim_result_no_next") IN('null','integer')),
 CHECK(typeof("reclaim_applied_ms") IN('null','integer')),
 CHECK(typeof("reclaim_result_count") IN('null','integer')),
 CHECK(typeof("reclaim_result_digest") IN('null','blob')),
 CHECK(typeof(control_variable_bytes)='integer' AND control_variable_bytes>=0),
 CHECK(typeof("control_variable_bytes") IN('null','integer'))
) WITHOUT ROWID;

