 CHECK(typeof(stage_id) IN('null','integer')),
 CHECK(typeof(ordinal) IN('null','integer')),
 CHECK(typeof(role) IN('null','text')),
 CHECK(typeof(source_ordinal) IN('null','integer')),
 CHECK(typeof(image_id) IN('null','text')),
 CHECK(typeof(origin) IN('null','text')),
 CHECK(typeof(locale) IN('null','text')),
 CHECK(typeof(attribution) IN('null','text')),
 CHECK(typeof(score) IN('null','integer','real'))
) WITHOUT ROWID;

CREATE TABLE artwork_material_intents(
 id TEXT PRIMARY KEY NOT NULL,
 owner_id INTEGER NOT NULL,
 owner_incarnation BLOB NOT NULL CHECK(length(owner_incarnation)=16),
 generation INTEGER NOT NULL CHECK(generation>0),
 revision INTEGER NOT NULL CHECK(revision>0),
 source_digest TEXT NOT NULL CHECK(length(source_digest)=64 AND source_digest NOT GLOB '*[^0-9a-f]*'),
 accepted_mime TEXT NOT NULL CHECK(accepted_mime IN('image/jpeg','image/png','image/webp')),
 accepted_width INTEGER NOT NULL CHECK(accepted_width>0),
 accepted_height INTEGER NOT NULL CHECK(accepted_height>0),
 large_edge INTEGER NOT NULL CHECK(large_edge IN(1280,1920,2560)),
 encoder_revision INTEGER NOT NULL CHECK(encoder_revision>0),
 state TEXT NOT NULL CHECK(state IN('prepared','installed','published','retiring','done')),
 expected_slots INTEGER NOT NULL CHECK(expected_slots IN(3,4)),
 staged_slots INTEGER NOT NULL DEFAULT 0 CHECK(staged_slots>=0 AND staged_slots<=expected_slots),
 retirement_token BLOB CHECK(retirement_token IS NULL OR length(retirement_token)=16),
 retirement_mask INTEGER NOT NULL DEFAULT 0 CHECK(retirement_mask BETWEEN 0 AND 15),
 reclaim_after_slot INTEGER NOT NULL DEFAULT -1 CHECK(reclaim_after_slot>=-1),
 reclaim_due_ms INTEGER CHECK(reclaim_due_ms IS NULL OR reclaim_due_ms>=0),
 FOREIGN KEY(owner_id,owner_incarnation) REFERENCES artwork_subject_jobs(id,command_incarnation),
 UNIQUE(id,owner_id,owner_incarnation),
 CHECK(state NOT IN('installed','published') OR staged_slots=expected_slots),
 CHECK((state='retiring')=(retirement_token IS NOT NULL)),
 CHECK((state IN('retiring','done'))=(reclaim_due_ms IS NOT NULL)),
 CHECK(reclaim_after_slot<expected_slots),
 CHECK(state IN('retiring','done') OR reclaim_after_slot=-1),
 CHECK(state='retiring' OR retirement_mask=0),
 CHECK(retirement_mask<(1<<expected_slots)),
 CHECK(typeof(id) IN('null','text')),
 CHECK(typeof(owner_id) IN('null','integer')),
 CHECK(typeof(owner_incarnation) IN('null','blob')),
 CHECK(typeof(generation) IN('null','integer')),
 CHECK(typeof(revision) IN('null','integer')),
 CHECK(typeof(source_digest) IN('null','text')),
 CHECK(typeof(accepted_mime) IN('null','text')),
 CHECK(typeof(accepted_width) IN('null','integer')),
 CHECK(typeof(accepted_height) IN('null','integer')),
 CHECK(typeof(large_edge) IN('null','integer')),
 CHECK(typeof(encoder_revision) IN('null','integer')),
 CHECK(typeof(state) IN('null','text')),
 CHECK(typeof(expected_slots) IN('null','integer')),
 CHECK(typeof(staged_slots) IN('null','integer')),
 CHECK(typeof(retirement_token) IN('null','blob')),
 CHECK(typeof(retirement_mask) IN('null','integer')),
 CHECK(typeof(reclaim_after_slot) IN('null','integer')),
 CHECK(typeof(reclaim_due_ms) IN('null','integer'))
);

