CREATE TABLE metadata_ip_receipts(
 owner_id TEXT NOT NULL,
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 command_sequence INTEGER NOT NULL CHECK(command_sequence>0),
 operation_id BLOB NOT NULL UNIQUE CHECK(length(operation_id)=16),
 request_digest BLOB NOT NULL CHECK(length(request_digest)=32),
 command_kind TEXT NOT NULL CHECK(command_kind IN('claim','renew','finish','begin','append','evidence_seal','set_begin','set_page','set_seal','accept','delta','reclaim')),
 accepted_revision INTEGER NOT NULL CHECK(accepted_revision>0),
 applied_ms INTEGER NOT NULL CHECK(applied_ms>=0),
 result_digest BLOB NOT NULL CHECK(length(result_digest)=32),
 result_phase TEXT NOT NULL,
 after_family INTEGER NOT NULL CHECK(after_family>=0),
 after_ordinal INTEGER NOT NULL CHECK(after_ordinal>=-1),
 after_key TEXT NOT NULL,
 result_count INTEGER NOT NULL CHECK(result_count>=0),
 result_bytes INTEGER NOT NULL CHECK(result_bytes>=0),
 terminal INTEGER NOT NULL CHECK(terminal IN(0,1)),
 evidence_id TEXT,
 evidence_subject_id INTEGER,
 parser_version TEXT,
 build_id TEXT,
 set_id TEXT,
 publication_id TEXT,
 seal_algorithm TEXT,
 seal_version INTEGER,
 seal_commitment BLOB,
 seal_rows INTEGER,
 seal_bytes INTEGER,
 proof_pin_count INTEGER NOT NULL DEFAULT 0 CHECK(proof_pin_count>=0),
 proof_revision INTEGER NOT NULL DEFAULT 1 CHECK(proof_revision>0),
 entity_id INTEGER NOT NULL CHECK(entity_id>0),
 provider TEXT NOT NULL,
 evidence_subject_kind TEXT CHECK(evidence_subject_kind IS NULL OR evidence_subject_kind IN('series','season','episode','collection','artist','release','recording')),
 evidence_provider_id TEXT,
 variable_bytes INTEGER GENERATED ALWAYS AS(length(CAST(owner_id AS BLOB))+length(command_incarnation)+length(operation_id)+length(request_digest)+length(result_digest)+length(CAST(command_kind AS BLOB))+length(CAST(result_phase AS BLOB))+length(CAST(after_key AS BLOB))+length(CAST(provider AS BLOB)) +coalesce(length(CAST(evidence_id AS BLOB)),0) +coalesce(length(CAST(parser_version AS BLOB)),0) +coalesce(length(CAST(build_id AS BLOB)),0) +coalesce(length(CAST(set_id AS BLOB)),0) +coalesce(length(CAST(publication_id AS BLOB)),0) +coalesce(length(CAST(seal_algorithm AS BLOB)),0) +coalesce(length(CAST(evidence_subject_kind AS BLOB)),0) +coalesce(length(CAST(evidence_provider_id AS BLOB)),0) +coalesce(length(seal_commitment),0)) VIRTUAL CHECK(variable_bytes>=0),
 PRIMARY KEY(owner_id,command_incarnation,command_sequence),
 UNIQUE(owner_id,command_incarnation,command_sequence,command_kind,evidence_id,evidence_subject_id,parser_version),
 UNIQUE(owner_id,command_incarnation,command_sequence,command_kind,set_id),
 FOREIGN KEY(owner_id,command_incarnation) REFERENCES metadata_provider_operations(id,command_incarnation) ON DELETE NO ACTION,
 FOREIGN KEY(evidence_id,evidence_subject_id) REFERENCES metadata_evidence(id,subject_id) ON DELETE NO ACTION,
 FOREIGN KEY(build_id,owner_id,command_incarnation) REFERENCES metadata_evidence_builds(id,owner_operation,owner_incarnation) ON DELETE NO ACTION,
 FOREIGN KEY(build_id,owner_id,command_incarnation,evidence_id) REFERENCES metadata_evidence_builds(id,owner_operation,owner_incarnation,evidence_id) ON DELETE NO ACTION ON UPDATE NO ACTION,
 FOREIGN KEY(set_id,owner_id,command_incarnation) REFERENCES metadata_publication_sets(id,ip_operation_id,ip_operation_incarnation) ON DELETE NO ACTION,
 FOREIGN KEY(publication_id,owner_id,command_incarnation) REFERENCES metadata_publications(id,operation_id,ip_proof_incarnation) ON DELETE NO ACTION,
 FOREIGN KEY(publication_id,owner_id,command_incarnation,evidence_id) REFERENCES metadata_publications(id,operation_id,ip_proof_incarnation,evidence_id) ON DELETE NO ACTION ON UPDATE NO ACTION,
 CHECK((evidence_id IS NULL)=(evidence_subject_id IS NULL)),
 CHECK((evidence_id IS NULL)=(parser_version IS NULL)),
 CHECK((command_kind IN('evidence_seal','set_seal'))=(seal_algorithm IS NOT NULL)),
 CHECK((seal_algorithm IS NULL)=(seal_version IS NULL) AND (seal_algorithm IS NULL)=(seal_commitment IS NULL) AND (seal_algorithm IS NULL)=(seal_rows IS NULL) AND (seal_algorithm IS NULL)=(seal_bytes IS NULL)),
 CHECK(seal_algorithm IS NULL OR (length(seal_algorithm)>0 AND seal_version>0 AND length(seal_commitment)=32 AND seal_rows>0 AND seal_bytes>0)),
 CHECK(command_kind<>'evidence_seal' OR (evidence_id IS NOT NULL AND build_id IS NOT NULL)),
 CHECK(command_kind NOT IN('set_begin','set_page','set_seal') OR set_id IS NOT NULL),
 CHECK(command_kind NOT IN('accept','delta') OR publication_id IS NOT NULL),
 CHECK((evidence_id IS NULL)=(evidence_subject_kind IS NULL) AND (evidence_id IS NULL)=(evidence_provider_id IS NULL)),
 FOREIGN KEY(evidence_id,provider,evidence_subject_kind,evidence_provider_id) REFERENCES metadata_evidence(id,provider,subject_kind,provider_id) ON DELETE NO ACTION ON UPDATE NO ACTION,
 FOREIGN KEY(owner_id,command_incarnation,entity_id,provider) REFERENCES metadata_provider_operations(id,command_incarnation,entity_id,provider) ON DELETE NO ACTION ON UPDATE NO ACTION
) WITHOUT ROWID, STRICT;

