 asset_id TEXT NOT NULL CHECK(asset_id IS NULL OR typeof(asset_id) IN('text')),
 inventory_object_id TEXT NOT NULL CHECK(inventory_object_id IS NULL OR typeof(inventory_object_id) IN('text')),
