 PRIMARY KEY(media_session_id),
 FOREIGN KEY(media_session_id) REFERENCES playback_sessions(id) ON DELETE NO ACTION ON UPDATE NO ACTION
) WITHOUT ROWID;

CREATE TABLE mp_direct_delivery(
